#include "AudioHealth.h"
static void testAudioHealth(){
    AudioHealth health(1000000);auto s=health.snapshot();expect(s.consistent&&!s.running&&s.callbacks==0&&s.deviceStarts==0,"callback health starts empty without inventing driver activity");
    health.prepare(48000,480);s=health.snapshot();expect(s.running&&s.rate==48000&&s.nominalBlock==480&&s.deviceStarts==1&&s.measurement==1,"device preparation starts a distinct measurement epoch");
    auto record=[&](int64 start,int frames,int64 used,bool output=true){health.end(health.begin(frames,start),start+used,output);};
    record(100000,480,2500);s=health.snapshot();expect(s.callbacks==1&&s.frames==480&&s.lastMs==2.5&&s.maxMs==2.5&&s.meanMs==2.5&&s.worstUtilization==25&&s.meanUtilization==25,"whole callback duration and load use actual frame count and sample rate");
    record(110000,480,10000);s=health.snapshot();expect(s.callbacks==2&&s.deadlineMisses==0&&s.worstUtilization==100&&s.lateStarts==0,"exact callback deadline is accepted and steady starts are not flagged");
    record(120000,480,12500);s=health.snapshot();expect(s.deadlineMisses==1&&s.maxMs==12.5&&s.worstUtilization==125&&s.meanUtilization>83&&s.meanUtilization<84,"actual application deadline overrun is counted separately from start timing");
    record(150000,240,1000,false);s=health.snapshot();expect(s.lateStarts==1&&s.estimatedMissingBlocks==2&&s.silentBlocks==1&&s.frames==1680&&s.maxStartGapMs==30,"late start uses previous block duration and silent outputs remain observable");
    record(155000,240,5000);s=health.snapshot();expect(s.deadlineMisses==1&&s.lateStarts==1&&s.frames==1920,"variable callback lengths have independent deadlines without false gap estimates");
    auto epoch=s.measurement;health.requestReset();expect(health.snapshot().resetPending&&health.snapshot().measurement==epoch,"UI reset is deferred until producer acknowledgement");record(900000,480,1000);s=health.snapshot();expect(!s.resetPending&&s.measurement==epoch+1&&s.callbacks==1&&s.frames==480&&s.deadlineMisses==0&&s.lateStarts==0&&s.deviceStarts==1,"reset clears measurements and gap baseline while preserving device lifetime counts");
    health.begin(0,910000);health.begin(-1,920000);health.begin(1048577,930000);s=health.snapshot();expect(s.invalidBlocks==3&&s.callbacks==1&&s.frames==480,"invalid or excessive frame counts cannot distort measured callback totals");
    record(940000,480,1000);health.end(health.begin(480,930000),929000);s=health.snapshot();expect(s.clockErrors==2&&s.lateStarts==0&&s.lastMs==0,"backward clock samples are identified without unsigned duration explosions");
    health.stopped();s=health.snapshot();expect(!s.running&&s.deviceStops==1&&s.callbacks==3,"device stop retains its last measurement and increments lifecycle once");health.stopped();expect(health.snapshot().deviceStops==1&&!health.begin(480,950000).valid,"duplicate release and callbacks after stop do not fabricate measurements");
    health.requestReset();health.prepare(96000,960);record(2000000,960,3000);s=health.snapshot();expect(s.deviceStarts==2&&s.deviceStops==1&&s.rate==96000&&s.callbacks==1&&s.meanUtilization==30&&s.lateStarts==0&&!s.resetPending,"restart consumes pending reset and establishes a new timing/rate baseline");
    health.prepare(NAN,512);expect(!health.snapshot().running&&!health.begin(512,1).valid,"invalid sample rate disables timing without division by zero");health.prepare(48000,0);expect(!health.snapshot().running,"invalid nominal device buffer is rejected for measurement");
    AudioHealth concurrent(1000000);concurrent.prepare(48000,480);std::atomic<bool> done{false},valid{true};std::atomic<int> observed{0};std::thread writer([&]{for(int i=0;i<10000;++i){auto token=concurrent.begin(480,100000+i*10000LL);concurrent.end(token,100100+i*10000LL);}done=true;});
    while(!done.load()){auto read=concurrent.snapshot();if(read.consistent){if(!(read.frames==read.callbacks*480&&std::isfinite(read.meanMs)&&read.deadlineMisses==0&&read.silentBlocks==0))valid=false;++observed;}if(observed.load()%100==0)concurrent.requestReset();}
    writer.join();s=concurrent.snapshot();expect(valid.load()&&s.consistent&&s.frames==s.callbacks*480&&s.deviceStarts==1,"concurrent measurement resets and bounded snapshots preserve complete-frame accounting");
    {Assets assets;auto project=emptyProject();auto engine=makeEngine(project,assets,File::getCurrentWorkingDirectory());engine->playing=false;Sample source;source.audio.setSize(2,1024);for(int ch=0;ch<2;++ch)for(int i=0;i<1024;++i)source.audio.setSample(ch,i,.2f);engine->audition(0,36,true);engine->audition(7,60,true);engine->preview(&source);engine->prepare(48000);AudioBuffer<float> out(2,512);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(out.getMagnitude(0,0,512)==0&&!engine->previewPlaying.load(),"reconfiguration discards queued drum/keyboard/preview audio instead of automatically sounding it after reconnect");engine->audition(0,36,true);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(out.getMagnitude(0,0,512)>.001f,"fresh explicit audition after reconfiguration still plays normally");}

}
